input.command:
node -e '
const fs = require("fs");
const path = require("path");
const root = "/work/workspace.dsl";
const out = [];
for (const line of fs.readFileSync(root, "utf8").split(/\r?\n/)) {
  const m = line.match(/^\s*!include\s+"([^"]+)"/);
  if (m) { out.push(fs.readFileSync(path.join("/work", m[1]), "utf8").replace(/\s+$/, "")); continue; }
  if (/^\s*!docs\b/.test(line)) continue;
  out.push(line);
}
fs.writeFileSync("/tmp/opencode/workspace.inlined.dsl", out.join("\n") + "\n");
console.log("written");
'

